CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- ----- venues -----
CREATE TABLE IF NOT EXISTS venues (
  venue_id    VARCHAR(20) PRIMARY KEY,
  venue_code  VARCHAR(40),
  venue_name  VARCHAR(200) NOT NULL,
  city        VARCHAR(80),
  address     TEXT,
  capacity    INT,
  status      VARCHAR(20) DEFAULT 'ACTIVE'
);

-- ----- events -----
CREATE TABLE IF NOT EXISTS events (
  event_id         SERIAL PRIMARY KEY,
  event_code       VARCHAR(40),
  title            VARCHAR(200) NOT NULL,
  artist           VARCHAR(150) NOT NULL,
  venue            VARCHAR(200) NOT NULL,
  venue_id         VARCHAR(20),
  starts_at        TIMESTAMPTZ NOT NULL,
  ends_at          TIMESTAMPTZ,
  sales_opens_at   TIMESTAMPTZ NOT NULL,
  sales_closes_at  TIMESTAMPTZ,
  quota_total      INT NOT NULL CHECK (quota_total > 0),
  price_idr        BIGINT NOT NULL CHECK (price_idr >= 0),
  status           VARCHAR(20) NOT NULL DEFAULT 'PUBLISHED',
  city             VARCHAR(80),
  country          VARCHAR(80),
  description      TEXT,
  gate_open        VARCHAR(40),
  age_rating       VARCHAR(80),
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ----- seat_categories -----
CREATE TABLE IF NOT EXISTS seat_categories (
  event_id   INT NOT NULL REFERENCES events(event_id) ON DELETE CASCADE,
  code       VARCHAR(20) NOT NULL,
  name       VARCHAR(120) NOT NULL,
  price_idr  BIGINT NOT NULL,
  quota      INT NOT NULL,
  color_hex  VARCHAR(7),
  PRIMARY KEY (event_id, code)
);

-- ----- seats (denah) -----
CREATE TABLE IF NOT EXISTS seats (
  event_id        INT NOT NULL REFERENCES events(event_id) ON DELETE CASCADE,
  seat_code       VARCHAR(20) NOT NULL,
  category        VARCHAR(40) NOT NULL DEFAULT 'REG',
  category_name   VARCHAR(120),
  row_label       VARCHAR(10) NOT NULL,
  seat_number     INT NOT NULL,
  section         VARCHAR(80),
  price_idr       BIGINT,
  color_hex       VARCHAR(7),
  pos_x           INT,
  pos_y           INT,
  PRIMARY KEY (event_id, seat_code)
);
CREATE INDEX IF NOT EXISTS idx_seats_event_cat ON seats(event_id, category);

-- ----- orders -----
CREATE TABLE IF NOT EXISTS orders (
  order_id      UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  event_id      INT NOT NULL REFERENCES events(event_id),
  qty           INT NOT NULL CHECK (qty > 0 AND qty <= 4),
  amount_idr    BIGINT NOT NULL,
  status        VARCHAR(20) NOT NULL DEFAULT 'CONFIRMED',
  client_ip     VARCHAR(64),
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_orders_event ON orders(event_id);
CREATE INDEX IF NOT EXISTS idx_orders_created ON orders(created_at);

CREATE TABLE IF NOT EXISTS order_events_audit (
  audit_id      BIGSERIAL PRIMARY KEY,
  order_id      UUID,
  event_id      INT NOT NULL,
  action        VARCHAR(40) NOT NULL,
  detail        JSONB,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_audit_event ON order_events_audit(event_id);

